      'src_color': THREE.SrcColorFactor,
      'dst_color': THREE.DstColorFactor,
      'src_alpha': THREE.SrcAlphaFactor,
      'dst_alpha': THREE.DstAlphaFactor,
      'one_minus_src_color': THREE.OneMinusSrcColorFactor,
