        // Simpler datapath for local serving for now
        let effective_datapath = '/media/'; // Relative to server root packages/janusweb/build/1.5.42/
        let defaultuipath = effective_datapath + 'assets/webui/default.json';

        console.log('[Client] datapath from config:', datapath);
